(* @case w4-n1 *)
(* @test
version: 1
input: source
runs:
  - name: cpu
    pipeline: shaped-f32-cpu
    profile: f32-ftz
    arguments:
      - name: a
        dtype: f32
        shape: [1]
        values: [0x7d24f35f]
      - name: b
        dtype: f32
        shape: [1]
        values: [0x7d3e596c]
      - name: c
        dtype: f32
        shape: [1]
        values: [0x7d57bf79]
  - name: metal
    pipeline: shaped-f32-metal
    profile: f32-ftz
    threads-per-group: 4
    arguments:
      - name: a
        dtype: f32
        shape: [1]
        values: [0x7d24f35f]
      - name: b
        dtype: f32
        shape: [1]
        values: [0x7d3e596c]
      - name: c
        dtype: f32
        shape: [1]
        values: [0x7d57bf79]
*)
(* @assert:cpu:result
[0xfb0e7500]
*)
(* @assert:cpu:shape
[1]
*)
(* @assert:metal:result
[0xfb0e7500]
*)
(* @assert:metal:shape
[1]
*)
(* @assert:metal:compare
cpu
*)
a * 0.1 + b - c

